import { stackTracks } from './stack-curriculum.js';
import { tracks } from './curriculum.js';
import { myCurriculum } from './my-curriculum.js';
import { learningPaths } from './learning-paths.js';

const myTracks = tracks.map(track => {
  const copy = myCurriculum[track.id];
  const modules = track.modules.map((group, index) => ({
    title: learningPaths[track.id]?.[index].title.my ?? copy.modules[index],
    exercises: group.exercises.map(exercise => {
      const { checkLabels, ...text } = exercise.my ?? copy.exercises[exercise.id];
      return {
        ...exercise,
        ...text,
        checks: exercise.checks.map((check, index) => ({ ...check, label: checkLabels[index] })),
      };
    }),
  }));
  return {
    ...track,
    title: copy.title,
    description: copy.description,
    modules,
    exercises: modules.flatMap(group => group.exercises),
  };
});

const withStack = (base, language) => [
  ...base.filter(track => track.id !== 'projects'),
  ...stackTracks(language),
  base.find(track => track.id === 'projects'),
];

export const curricula = { en: withStack(tracks, 'en'), my: withStack(myTracks, 'my') };
